  var js = "\n/**\n    Template name: Overlay v2 - Google Consent Mode v2\n    URI: https://cookieinformation.com\n    Version 1.2.1\n **/\n\nconst coiOverlay = document.getElementById(\"coiOverlay\");\nconst coiBannerWrapper = document.getElementById(\"coi-banner-wrapper\");\nconst coiRenewBtn = document.getElementById(\"Coi-Renew\");\nconst coiPurposesList = document.getElementsByClassName(\"coi-purpose-list\");\n\n/* LOGO FUNCTION START */\n(function () {\n    const imagePath = \"\"; // Change this to your own logo URL\n    const container = document.getElementsByClassName(\"coi-banner__branding-wrapper\");\n\n    if (imagePath) {\n        for (const el of Array.from(container)) {\n            const logo = document.createElement(\"img\");\n            logo.style.width = \"180px\"; // Change width for better fit\n            logo.src = imagePath;\n            logo.alt = \"logo\";\n            el.insertBefore(logo, el.childNodes[0]);\n        }\n    } else {\n        for (const el of Array.from(container)) {\n            const logo = document.createElement(\"span\");\n            logo.setAttribute(\"aria-hidden\", \"true\");\n            el.insertBefore(logo, el.childNodes[0]);\n        }\n    }\n})();\n/* LOGO FUNCTION END */\n\nfunction insertPurposesInList() {\n    if (coiPurposesList) {\n        const purposesElements =\n            document.getElementById(\"coi-banner-categories\")?.innerHTML ?? \"\";\n        for (const list of Array.from(coiPurposesList)) {\n            list.innerHTML = purposesElements;\n        }\n    }\n}\n\nfunction trapFocusInModal(modal) {\n    modal = document.getElementById(modal);\n    const focusableEl = modal.querySelectorAll(\n        'button:not([disabled]), a[href]:not([disabled]), input:not([disabled]), select, textarea:not([disabled]), [tabindex]:not([tabindex=\"-1\"])'\n    );\n    const firstFocusableEl = focusableEl[0];\n    const lastFocusableEl = focusableEl[focusableEl.length - 1];\n    const KEYCODE_TAB = 9;\n    coiBannerWrapper.focus();\n\n    const ctlFocus = (e) => {\n        const isTabPressed = e.key === \"Tab\" || e.keyCode === KEYCODE_TAB;\n        if (!isTabPressed) {\n            return;\n        }\n        if (e.shiftKey) {\n            /* shift + tab */ if (document.activeElement === firstFocusableEl) {\n                lastFocusableEl.focus();\n                e.preventDefault();\n            }\n        } else {\n            /* tab */ if (document.activeElement === lastFocusableEl) {\n                firstFocusableEl.focus();\n                e.preventDefault();\n            }\n        }\n        document.activeElement.scrollIntoView();\n    };\n\n    modal.addEventListener(\"keydown\", ctlFocus);\n}\n\nfunction checkConsentsState() {\n    const checkedElements = document.querySelectorAll(\n        \".coi__checkbox:not(#cookie_cat_necessary):checked\"\n    );\n    setConsentOption(checkedElements.length > 0);\n}\n\nconst checkboxes = document.querySelectorAll(\n    \".coi__checkbox:not(#cookie_cat_necessary)\"\n);\n\nfor (const checkbox of Array.from(checkboxes)) {\n    checkbox.addEventListener(\"change\", () => {\n        checkConsentsState();\n    });\n}\n\nfunction setConsentOption(state) {\n    const updateButton = document.getElementById(\"updateButton\");\n    const declineButton = document.getElementById(\"declineButton\");\n\n    if (state) {\n        declineButton.style.display = \"none\";\n        declineButton.setAttribute(\"tabindex\", -1);\n        updateButton.style.display = \"flex\";\n        updateButton.setAttribute(\"tabindex\", 0);\n    } else {\n        updateButton.style.display = \"none\";\n        updateButton.setAttribute(\"tabindex\", -1);\n        declineButton.style.display = \"flex\";\n        declineButton.setAttribute(\"tabindex\", 0);\n    }\n}\n\nfunction TogglePage(triggerEl, targetId) {\n    const pages = document.getElementsByClassName(\"coi-banner__page\");\n    const links = document.getElementsByClassName(\"coi-banner__lastpage\");\n    const target = document.getElementById(targetId);\n\n    if (!target) return;\n\n    for (const page of Array.from(pages)) {\n        page.style.display = \"none\";\n    }\n\n    for (const link of Array.from(links)) {\n        link.classList.remove(\"activeTab\");\n    }\n\n    target.style.display = \"block\";\n    triggerEl.classList.add(\"activeTab\");\n    trapFocusInModal(targetId);\n}\n\nfunction toggleDetails() {\n    const toggleBtn = document.getElementById(\"coi-details-toggle\");\n    const categoryWrapper = document.getElementById(\"coiConsentBannerCategoriesWrapper\");\n\n    if (!toggleBtn || !categoryWrapper) return;\n\n    const isExpanded = toggleBtn.getAttribute(\"aria-expanded\") === \"true\";\n    toggleBtn.setAttribute(\"aria-expanded\", !isExpanded);\n\n    const showText = toggleBtn.querySelector(\".coi-toggle-show-details\");\n    const hideText = toggleBtn.querySelector(\".coi-toggle-hide-details\");\n\n    if (showText) showText.style.display = isExpanded ? \"inline\" : \"none\";\n    if (hideText) hideText.style.display = isExpanded ? \"none\" : \"inline\";\n\n    categoryWrapper.style.display = isExpanded ? \"none\" : \"block\";\n    categoryWrapper.setAttribute(\"aria-hidden\", isExpanded);\n\n    const categories = document.querySelectorAll(\".coi-consent-banner__category-name\");\n    for (const category of Array.from(categories)) {\n        category.setAttribute(\"tabindex\", isExpanded ? -1 : 0);\n\n        if (isExpanded) {\n            category.classList.remove(\"ci-btn-tab-active\");\n            category.setAttribute(\"aria-expanded\", \"false\");\n        }\n    }\n\n    if (isExpanded) {\n        const categoryTabs = document.querySelectorAll(\".coi-consent-banner__description-container\");\n        for (const categoryTab of Array.from(categoryTabs)) {\n            categoryTab.classList.remove(\"tab-panel-active\");\n            categoryTab.setAttribute(\"aria-hidden\", \"true\");\n\n            const links = categoryTab.querySelectorAll(\"a\");\n            for (const link of Array.from(links)) {\n                link.setAttribute(\"tabindex\", -1);\n            }\n        }\n    }\n}\n\nfunction toggleCookieDetails(btn, tab) {\n    const tabContent = document.getElementById(tab);\n    btn.classList.toggle(\"ci-btn-tab-active\");\n    btn.setAttribute(\n        \"aria-expanded\",\n        btn.getAttribute(\"aria-expanded\") === \"false\" ? \"true\" : \"false\"\n    );\n\n    tabContent.classList.toggle(\"tab-panel-active\");\n    tabContent.setAttribute(\n        \"aria-hidden\",\n        tabContent.getAttribute(\"aria-hidden\") === \"false\" ? \"true\" : \"false\"\n    );\n\n    const links = tabContent.querySelectorAll(\"a\");\n    const tabIndexValue = tabContent.classList.contains(\"tab-panel-active\") ? 0 : -1;\n    for (const link of Array.from(links)) {\n        link.setAttribute(\"tabindex\", tabIndexValue);\n    }\n}\n\ncoiOverlay.addEventListener(\n    \"click\",\n    (e) => {\n        if (e.target === e.currentTarget) {\n            e.preventDefault();\n            coiBannerWrapper.classList.remove(\"ci-bounce\");\n            coiBannerWrapper.offsetWidth;\n            coiBannerWrapper.classList.add(\"ci-bounce\");\n        }\n    },\n    false\n);\n\nfunction togglePlaceholderElementsOnConsent() {\n    const consentPlaceholders = document.getElementsByClassName(\n        \"consent-placeholder\"\n    );\n    if (consentPlaceholders) {\n        for (const placeholder of Array.from(consentPlaceholders)) {\n            const dataCategory = placeholder.getAttribute(\"data-category\");\n            if (!CookieInformation.getConsentGivenFor(dataCategory)) {\n                placeholder.style.display = \"block\";\n            } else {\n                placeholder.style.display = \"none\";\n            }\n        }\n    }\n}\n\nfunction setNoScroll(state) {\n    const htmlElement = document.getElementsByTagName(\"html\")[0];\n    if (state) {\n        htmlElement.classList.add(\"noScroll\");\n    } else {\n        htmlElement.classList.remove(\"noScroll\");\n    }\n}\n\nfunction showCookieBanner() {\n    insertPurposesInList();\n    coiOverlay.style.display = \"flex\";\n    setNoScroll(true);\n    coiBannerWrapper.setAttribute(\"aria-hidden\", \"false\");\n    coiOverlay.setAttribute(\"aria-hidden\", \"false\");\n    requestAnimationFrame(() => {\n        trapFocusInModal(\"coiPage-1\");\n    });\n    checkConsentsState();\n\n    coiRenewBtn.style.display = \"none\";\n    togglePlaceholderElementsOnConsent();\n}\n\nfunction hideCookieBanner() {\n    if (coiOverlay.contains(document.activeElement)) {\n        document.activeElement.blur();\n    }\n\n    if (coiRenewBtn && coiRenewBtn.offsetParent !== null) {\n        coiRenewBtn.focus();\n    } else {\n        document.body.setAttribute(\"tabindex\", \"-1\");\n        document.body.focus();\n        document.body.removeAttribute(\"tabindex\");\n    }\n\n    coiBannerWrapper.setAttribute(\"aria-hidden\", \"true\");\n    coiOverlay.setAttribute(\"aria-hidden\", \"true\");\n    coiOverlay.style.display = \"none\";\n    setNoScroll(false);\n\n    coiRenewBtn.style.display = \"block\";\n    togglePlaceholderElementsOnConsent();\n}\n";
